      const settings={name:text(body.name,'El nombre de la tienda',150,true),currency:text(body.currency,'La moneda',3,true).toUpperCase(),address:text(body.address,'La dirección',500),phone:text(body.phone,'El teléfono',60),taxId:text(body.taxId,'La identificación fiscal',100),receiptFooter:text(body.receiptFooter,'El mensaje del recibo',500)};
      if(!/^[A-Z]{3}$/.test(settings.currency)) throw new APIError('Selecciona una moneda válida.');
      try {new Intl.NumberFormat('es',{style:'currency',currency:settings.currency}).format(0);}catch {throw new APIError('Selecciona una moneda válida.');}
