        if(!item || typeof item!=='object') throw new APIError(`El producto ${index+1} no es válida.`);
        const category=item.category??'clothing';
        if(!['clothing','footwear','accessory'].includes(category)) throw new APIError('Selecciona un tipo de producto válido.');
        const price=money(item.price,`El precio del producto ${index+1}`);
        if(!Number.isInteger(item.quantity)||item.quantity<1||item.quantity>9999) throw new APIError(`La cantidad del producto ${index+1} debe ser un entero entre 1 y 9999.`);
